using Microsoft.Data.Sqlite;using System.Text.Json;
namespace Satusehat.IntegrationSdk;
internal sealed class SQLiteQueue:IAsyncDisposable{readonly SqliteConnection db;static string Now()=>DateTimeOffset.UtcNow.ToString("O");public SQLiteQueue(string path){db=new SqliteConnection($"Data Source={path}");db.Open();using var cmd=db.CreateCommand();cmd.CommandText="PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS integration_events(event_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,operation TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,payload_json TEXT,status TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 0,http_status INTEGER,error_category TEXT,error_message TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,next_retry_at TEXT);CREATE INDEX IF NOT EXISTS idx_integration_events_ready ON integration_events(status,next_retry_at,created_at);";cmd.ExecuteNonQuery();}public string Enqueue(string org,string op,string rt,string? id,string? payload){op=op.ToUpperInvariant();if(op != "GET" && op != "POST" && op != "PUT" && op != "PATCH")throw new ArgumentException("unsupported operation");if((op == "PUT" || op == "PATCH") && string.IsNullOrWhiteSpace(id))throw new ArgumentException("resourceId required for PUT/PATCH");if(payload is not null)JsonDocument.Parse(payload).Dispose();var eid=Guid.NewGuid().ToString(),n=Now();using var c=db.CreateCommand();c.CommandText="INSERT INTO integration_events(event_id,organization_id,operation,resource_type,resource_id,payload_json,status,attempt,created_at,updated_at)VALUES($e,$o,$op,$rt,$id,$p,'QUEUED',0,$n,$n)";c.Parameters.AddWithValue("$e",eid);c.Parameters.AddWithValue("$o",org);c.Parameters.AddWithValue("$op",op);c.Parameters.AddWithValue("$rt",rt);c.Parameters.AddWithValue("$id",(object?)id??DBNull.Value);c.Parameters.AddWithValue("$p",(object?)payload??DBNull.Value);c.Parameters.AddWithValue("$n",n);c.ExecuteNonQuery();return eid;}public List<QueueEvent> Ready(int limit){var outp=new List<QueueEvent>();using var c=db.CreateCommand();c.CommandText="SELECT event_id,operation,resource_type,resource_id,payload_json,attempt FROM integration_events WHERE status IN ('QUEUED','RETRYING','RATE_LIMITED') AND (next_retry_at IS NULL OR next_retry_at<=$n) ORDER BY created_at LIMIT $l";c.Parameters.AddWithValue("$n",Now());c.Parameters.AddWithValue("$l",limit);using var r=c.ExecuteReader();while(r.Read())outp.Add(new(r.GetString(0),r.GetString(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.GetInt32(5)));return outp;}public int MarkProcessing(string id){using(var c=db.CreateCommand()){c.CommandText="UPDATE integration_events SET status='PROCESSING',attempt=attempt+1,updated_at=$n WHERE event_id=$e";c.Parameters.AddWithValue("$n",Now());c.Parameters.AddWithValue("$e",id);c.ExecuteNonQuery();}using var q=db.CreateCommand();q.CommandText="SELECT attempt FROM integration_events WHERE event_id=$e";q.Parameters.AddWithValue("$e",id);return Convert.ToInt32(q.ExecuteScalar());}public void Complete(string id,EventStatus status,int? http=null,string? cat=null,string? msg=null,string? next=null){using var c=db.CreateCommand();c.CommandText="UPDATE integration_events SET status=$s,http_status=$h,error_category=$c,error_message=$m,updated_at=$n,next_retry_at=$r WHERE event_id=$e";c.Parameters.AddWithValue("$s",status.ToString());c.Parameters.AddWithValue("$h",(object?)http??DBNull.Value);c.Parameters.AddWithValue("$c",(object?)cat??DBNull.Value);c.Parameters.AddWithValue("$m",(object?)(msg is null?null:msg[..Math.Min(2000,msg.Length)])??DBNull.Value);c.Parameters.AddWithValue("$n",Now());c.Parameters.AddWithValue("$r",(object?)next??DBNull.Value);c.Parameters.AddWithValue("$e",id);c.ExecuteNonQuery();}public async ValueTask DisposeAsync()=>await db.DisposeAsync();}
